opic", "title": "Ecclesiastes and ambiguity", "children": [{"id": "b268a443-b95e-408e-be53-f6529965dd92", "type": "concept", "title": "Vanity and vapor"}, {"id": "fa11282b-3f8d-4b93-b0d9-f52b02ef319d", "type": "concept", "title": "Death and time"}, {"id": "37556d50-9680-40d7-ab3b-85072c403602", "type": "concept", "title": "Joy, limits, and skepticism"}], "description": "Ecclesiastes teaches students how biblical wisdom can question certainty and easy meaning."}]}, {"id": "d11a43d9-b0a0-4c3c-ae93-21ff4f15bea4", "type": "topic", "title": "Exile, Trauma, Return, Restoration, and Scriptural Formation", "description": "Interprets exile and return as historical crisis, theological reckoning, and engine of literary preservation.", "children": [{"id": "4445f390-1cb6-4b75-80f8-76d08c79ee9d", "type": "subtopic", "title": "Exile as crisis", "children": [{"id": "9cc10ad4-2061-4df7-a24f-2506f05d55e8", "type": "concept", "title": "Fall of Jerusalem"}, {"id": "12c57e57-f213-4c0c-8724-85e8728ecf33", "type": "concept", "title": "Temple destruction"}, {"id": "ee4e1135-91d0-4ffc-a1bd-e0829aee6496", "type": "concept", "title": "Displacement and identity"}], "description": "Students examine exile as political catastrophe, theological problem, and literary turning point."}, {"id": "86f6c73c-aeb7-475e-b5e4-d8ed0a7aa52b", "type": "subtopic", "title": "Exilic and postexilic voices", "children": [{"id": "c433f44a-351e-45d7-945b-db13eec232f7", "type": "concept", "title": "Jeremiah and Ezekiel"}, {"id": "e59ed97a-07ba-49a0-bb19-f1cd95eeaaba", "type": "concept", "title": "Second Isaiah"}, {"id": "59534a67-3cd2-4d87-9739-aca2bdb67b84", "type": "concept", "title": "Ezra and Nehemiah"}], "description": "The course reads texts that reimagine community after devastation."}, {"id": "95e51644-6300-4b66-ae69-dcca9946ca7c", "type": "subtopic", "title": "Scriptural formation", "children": [{"id": "203cfee1-8c6a-4c0c-a69e-0b437a8294c7", "type": "concept", "title": "Scribal culture"}, {"id": "d2a212cb-e875